const d = msg.payload;
const T = d.temperatura;
const HR = d.humedad;

if (typeof T === "number" && typeof HR === "number" && HR > 0 && HR <= 100) {
    const es = 0.6108 * Math.exp(17.27 * T / (T + 237.3));
    d.dpv = +(es * (1 - HR / 100)).toFixed(3);
    const g = Math.log(HR / 100) + 17.27 * T / (237.3 + T);
    d.punto_rocio = +(237.3 * g / (17.27 - g)).toFixed(2);
    d.margen_rocio = +(T - d.punto_rocio).toFixed(2);
}
return msg;

