msg.pedido = msg.payload;
msg.query = "from(bucket: "estacion")
  |> range(start: 2020-01-01T00:00:00Z)
  |> filter(fn: (r) => r._measurement == "ciclos" or r._measurement == "estado_estacion")
  |> last()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")";
return msg;

const filas = msg.payload || [];
const ciclos = filas
    .filter(r => r._measurement === "ciclos" && r.estado !== "anulado")
    .map(r => ({ciclo: r.ciclo, lote: r.lote, ubicacion: r.ubicacion, inicio: r.inicio, fin: r.fin, tbase: r.tbase, estado: r.estado}))
    .sort((a, b) => b.inicio.localeCompare(a.inicio));
const aviso = filas.find(r => r._measurement === "estado_estacion" && r.revisar_lote === 1);

msg.payload = {
