msg.pedido = msg.payload;
msg.query = "from(bucket: "estacion")
  |> range(start: 2020-01-01T00:00:00Z)
  |> filter(fn: (r) => r._measurement == "ciclos" or r._measurement == "estado_estacion")
  |> last()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")";
return msg;

// Recibe lo que mandó el formulario (msg.pedido) y los ciclos guardados (msg.payload)
const p = msg.pedido || {};
const filas = msg.payload || [];
const ciclos = filas.filter(r => r._measurement === "ciclos" && r.estado !== "anulado");
const activo = ciclos.find(r => r.estado === "activo");
const puntos = [];

const hoy = new Date(Date.now() - 5 * 3600000).toISOString().slice(0, 10);
function diaAnterior(f) {
    const d = new Date(f + "T12:00:00Z");
    d.setUTCDate(d.getUTCDate() - 1);
    return d.toISOString().slice(0, 10);
}
function error(texto) {
    msg.statusCode = 400;
    msg.payload = {ok: false, error: texto};
    return [null, msg];
}
function escribir(ciclo, campos) {
    puntos.push({measurement: "ciclos", tags: {ciclo: ciclo}, fields: campos});
}
function validar(d) {
    if (!/^\d+$/.test(d.lote || "")) return "El código del lote debe ser numérico.";
    if (!/^\d{4}-\d{2}-\d{2}$/.test(d.inicio || "")) return "La fecha de inicio no es válida.";
    if (d.inicio > hoy) return "La fecha de inicio no puede ser futura.";
    if (typeof d.tbase !== "number" || isNaN(d.tbase) || d.tbase < 0 || d.tbase > 20) return "La T-base debe estar entre 0 y 20 °C.";
    return "";
}

const nuevo = {
    lote: String(p.lote || "").trim(),
    ubicacion: String(p.ubicacion || "").trim().slice(0, 80),
    inicio: p.inicio,
    tbase: Number(p.tbase)
};

if (p.accion === "nuevo") {
    const e = validar(nuevo);
    if (e) return error(e);
    const id = nuevo.lote + "_" + nuevo.inicio;
    if (ciclos.some(c => c.ciclo === id)) return error("Ya existe un ciclo del lote " + nuevo.lote + " con esa fecha de inicio.");
    if (activo) {
        if (nuevo.inicio <= activo.inicio) return error("El ciclo nuevo debe empezar después del " + activo.inicio + ", que es cuando empezó el actual.");
        escribir(activo.ciclo, {lote: activo.lote, ubicacion: activo.ubicacion, inicio: activo.inicio, fin: diaAnterior(nuevo.inicio), tbase: activo.tbase, estado: "cerrado"});
    }
    escribir(id, Object.assign({}, nuevo, {fin: "", estado: "activo"}));
    msg.resumen = "Ciclo del lote " + nuevo.lote + " iniciado desde el " + nuevo.inicio + ".";
}
else if (p.accion === "editar") {
    if (!activo) return error("No hay un ciclo activo para corregir.");
    const e = validar(nuevo);
    if (e) return error(e);
    if (nuevo.inicio === activo.inicio && nuevo.lote === activo.lote) {
        escribir(activo.ciclo, Object.assign({}, nuevo, {fin: "", estado: "activo"}));
    } else {
        const id = nuevo.lote + "_" + nuevo.inicio;
        const anterior = ciclos.find(c => c.estado === "cerrado" && c.fin === diaAnterior(activo.inicio));
        if (anterior && nuevo.inicio <= anterior.inicio) return error("La fecha debe ser posterior al " + anterior.inicio + ", inicio del ciclo anterior.");
        escribir(activo.ciclo, {lote: activo.lote, ubicacion: activo.ubicacion, inicio: activo.inicio, fin: activo.fin, tbase: activo.tbase, estado: "anulado"});
        escribir(id, Object.assign({}, nuevo, {fin: "", estado: "activo"}));
        if (anterior) escribir(anterior.ciclo, {lote: anterior.lote, ubicacion: anterior.ubicacion, inicio: anterior.inicio, fin: diaAnterior(nuevo.inicio), tbase: anterior.tbase, estado: "cerrado"});
    }
    msg.resumen = "Ciclo actual corregido.";
}
else if (p.accion === "terminar") {
    if (!activo) return error("No hay un ciclo activo para terminar.");
    const fin = p.fin || hoy;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(fin) || fin < activo.inicio || fin > hoy) return error("La fecha de fin debe estar entre " + activo.inicio + " y hoy.");
    escribir(activo.ciclo, {lote: activo.lote, ubicacion: activo.ubicacion, inicio: activo.inicio, fin: fin, tbase: activo.tbase, estado: "cerrado"});
    msg.resumen = "Ciclo del lote " + activo.lote + " terminado el " + fin + ".";
}
else if (p.accion === "mismo_lote") {
    msg.resumen = "Confirmado: la estación sigue en el mismo lote.";
}
else {
    return error("Acción desconocida.");
}

// Cualquier decisión quita el aviso de "revisar lote"
puntos.push({measurement: "estado_estacion", fields: {revisar_lote: 0, mensaje: ""}});
msg.payload = puntos;
return [msg, null];

msg.statusCode = 200;
msg.payload = {ok: true, mensaje: msg.resumen};
return msg;

msg.statusCode = 500;
msg.payload = {ok: false, error: "No se pudo guardar en InfluxDB: " + (msg.error ? msg.error.message : "")};
return msg;

msg.statusCode = 500;
msg.payload = {ok: false, error: "No se pudo leer InfluxDB: " + (msg.error ? msg.error.message : "")};
return msg;

// Última lectura guardada antes de que arrancara Node-RED
const hasta = new Date(Date.now() - 30000).toISOString();
msg.topic = "arranque";
msg.query = 'from(bucket: "estacion") |> range(start: -400d, stop: ' + hasta + ') ' +
    '|> filter(fn: (r) => r._measurement == "datos") |> group() |> last() |> keep(columns: ["_time"])';
return msg;

// Si la estación pasa más de HORAS sin mandar datos (apagada o movida),
// deja un aviso para que alguien confirme si sigue en el mismo lote.
const HORAS = 6;

function revisar(t) {
    const ultimo = context.get("ultimo");
    context.set("ultimo", t);
    if (!ultimo || t - ultimo < HORAS * 3600000) return null;
    const f = x => new Date(x - 5 * 3600000).toISOString().slice(0, 16).replace("T", " ");
    const horas = ((t - ultimo) / 3600000).toFixed(1);
    msg.payload = [{measurement: "estado_estacion", fields: {
        revisar_lote: 1,
        mensaje: "La estación estuvo sin datos desde " + f(ultimo) + " hasta " + f(t) + " (" + horas + " h). ¿Sigue en el mismo lote?"
    }}];
    return msg;
}

if (msg.topic === "arranque") {
    const fila = (msg.payload || [])[0];
    if (fila && !context.get("ultimo")) context.set("ultimo", new Date(fila._time).getTime());
    context.set("listo", true);
    const pendiente = context.get("pendiente");
    context.set("pendiente", null);
    return pendiente ? revisar(pendiente) : null;
}

if (!context.get("listo")) {
    if (!context.get("pendiente")) context.set("pendiente", Date.now());
    return null;
}
return revisar(Date.now());

msg.query = "from(bucket: "estacion")
  |> range(start: -30d)
  |> filter(fn: (r) => r._measurement == "datos")
  |> last()
  |> keep(columns: ["_field", "_value"])";
return msg;

// Solo campos numéricos (los que se pueden promediar)
msg.campos = (msg.payload || []).filter(r => typeof r._value === "number").map(r => r._field).sort();
msg.query = "from(bucket: "estacion")
  |> range(start: 2020-01-01T00:00:00Z)
  |> filter(fn: (r) => r._measurement == "ciclos")
  |> last()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.estado != "anulado")";
return msg;

const ciclos = (msg.payload || [])
    .map(r => ({ciclo: r.ciclo, lote: r.lote, ubicacion: r.ubicacion, inicio: r.inicio, fin: r.fin}))
    .sort((a, b) => b.inicio.localeCompare(a.inicio));
msg.payload = {campos: msg.campos, ciclos: ciclos};
return msg;

msg.parametros = msg.req.query || {};
msg.query = "from(bucket: "estacion")
  |> range(start: 2020-01-01T00:00:00Z)
  |> filter(fn: (r) => r._measurement == "ciclos")
  |> last()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.estado != "anulado")";
return msg;

// Valida los criterios de búsqueda y arma la consulta
const MAX_FILAS = 100000;
const p = msg.parametros;
const ciclos = (msg.payload || []).filter(c => c.inicio);
msg.ciclos = ciclos;

function error(texto) {
    msg.statusCode = 400;
    msg.headers = {"Content-Type": "application/json; charset=utf-8"};
    msg.payload = {ok: false, error: texto};
    return [null, msg];
}
const fechaOk = f => /^\d{4}-\d{2}-\d{2}$/.test(f || "");
const hoy = new Date(Date.now() - 5 * 3600000).toISOString().slice(0, 10);

let desde = p.desde, hasta = p.hasta;
if (p.ciclo) {
    const c = ciclos.find(x => x.ciclo === p.ciclo);
    if (!c) return error("No existe el ciclo " + p.ciclo + ".");
    desde = c.inicio;
    hasta = c.fin || hoy;
}
if (!fechaOk(desde) || !fechaOk(hasta)) return error("Elija un ciclo o escriba las fechas desde y hasta (AAAA-MM-DD).");
if (hasta < desde) return error("La fecha hasta es anterior a la fecha desde.");

const inicio = new Date(desde + "T00:00:00-05:00");
const fin = new Date(new Date(hasta + "T00:00:00-05:00").getTime() + 86400000);
msg.rango = {desde: desde, hasta: hasta};
msg.tipo = p.tipo === "diario" ? "diario" : "lecturas";
msg.formato = p.formato === "codigo" ? "codigo" : "excel";
msg.vista = p.vista === "1";

const encabezado = 'import "date"\nimport "timezone"\noption location = timezone.location(name: "America/Bogota")\n\n';

if (msg.tipo === "diario") {
    msg.query = encabezado + 'from(bucket: "estacion")\n' +
        '  |> range(start: ' + inicio.toISOString() + ', stop: ' + fin.toISOString() + ')\n' +
        '  |> filter(fn: (r) => r._measurement == "diario")\n' +
        '  |> keep(columns: ["_time", "_field", "_value"])\n' +
        '  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")\n' +
        '  |> sort(columns: ["_time"])';
    return [msg, null];
}

const campos = String(p.campos || "").split(",").map(s => s.trim()).filter(s => s);
if (!campos.length) return error("Elija al menos una variable.");
if (campos.some(c => !/^[A-Za-z0-9_]+$/.test(c))) return error("Nombre de variable no válido.");
msg.campos = campos;

const INTERVALOS = {"0": 5, "1m": 60, "5m": 300, "15m": 900, "1h": 3600, "1d": 86400};
const intervalo = p.intervalo in INTERVALOS ? p.intervalo : "0";
msg.intervalo = intervalo;

let hd = 0, hh = 24;
if (p.hora_desde !== undefined && p.hora_desde !== "") hd = parseInt(p.hora_desde, 10);
if (p.hora_hasta !== undefined && p.hora_hasta !== "") hh = parseInt(p.hora_hasta, 10);
if (isNaN(hd) || isNaN(hh) || hd < 0 || hh > 24 || hd >= hh) return error("El horario debe ir de 0 a 24 y la hora inicial ser menor que la final.");
msg.horario = {desde: hd, hasta: hh};

const segundos = (fin - inicio) / 1000 * (hh - hd) / 24;
const estimadas = Math.ceil(segundos / INTERVALOS[intervalo]);
if (!msg.vista && estimadas > MAX_FILAS) {
    return error("La descarga tendría unas " + estimadas.toLocaleString("es-CO") + " filas (máximo " +
        MAX_FILAS.toLocaleString("es-CO") + "). Use un intervalo más grande o un rango más corto.");
}

msg.query = encabezado + 'from(bucket: "estacion")\n' +
    '  |> range(start: ' + inicio.toISOString() + ', stop: ' + fin.toISOString() + ')\n' +
    '  |> filter(fn: (r) => r._measurement == "datos" and (' + campos.map(c => 'r._field == "' + c + '"').join(" or ") + '))\n' +
    (hd > 0 || hh < 24 ? '  |> hourSelection(start: ' + hd + ', stop: ' + (hh - 1) + ')\n' : '') +
    (intervalo !== "0" ? '  |> aggregateWindow(every: ' + intervalo + ', fn: mean, createEmpty: false, timeSrc: "_start")\n' : '') +
    '  |> keep(columns: ["_time", "_field", "_value"])\n' +
    '  |> group()\n' +
    '  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")\n' +
    '  |> sort(columns: ["_time"])\n' +
    '  |> limit(n: ' + (msg.vista ? 20 : MAX_FILAS) + ')';
return [msg, null];

// Arma el CSV (o la vista previa) con lote y ubicación según el ciclo de cada fecha
const excel = msg.formato === "excel";
const sep = excel ? ";" : ",";
const filas = msg.payload || [];
const ciclos = msg.ciclos || [];

const local = t => new Date(new Date(t).getTime() - 5 * 3600000).toISOString().slice(0, 19);
function cicloDe(dia) {
    return ciclos.find(c => c.inicio <= dia && (!c.fin || dia <= c.fin)) || {};
}
function numero(v, dec) {
    if (typeof v !== "number" || isNaN(v)) return "";
    const s = String(+v.toFixed(dec));
    return excel ? s.replace(".", ",") : s;
}
function texto(v) {
    const s = v === undefined || v === null ? "" : String(v);
    return /[";,\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
const hms = s => typeof s === "number" ? new Date(s * 1000).toISOString().slice(11, 19) : "";

let columnas, datos;
if (msg.tipo === "diario") {
    columnas = ["fecha", "lote", "ubicacion", "t_max", "t_min", "t_media", "gdd", "gdd_acumulado", "dli",
                "inicio_luz", "fin_luz", "fotoperiodo", "fotoperiodo_h", "cambio_fotoperiodo_min", "luz_medida_con", "horas_con_datos"];
    const acumulado = {};
    let fotoAnterior = null;
    datos = filas.map(r => {
        const conPar = typeof r.fotoperiodo === "number";
        const foto = conPar ? r.fotoperiodo : r.fotoperiodo_lux;
        const ini = conPar ? r.inicio_luz : r.inicio_luz_lux;
        const fil = conPar ? r.fin_luz : r.fin_luz_lux;
        const cambio = (typeof foto === "number" && typeof fotoAnterior === "number") ? (foto - fotoAnterior) / 60 : null;
        if (typeof foto === "number") fotoAnterior = foto;
        const dia = local(r._time).slice(0, 10);
        const c = cicloDe(dia);
        let gdd = null, acum = null;
        if (c.ciclo && typeof r.tmedia === "number") {
            const tb = ciclos.find(x => x.ciclo === c.ciclo).tbase;
            gdd = r.tmedia > tb ? r.tmedia - tb : 0;
            acumulado[c.ciclo] = (acumulado[c.ciclo] || 0) + gdd;
            acum = acumulado[c.ciclo];
        }
        return [dia, texto(c.lote), texto(c.ubicacion), numero(r.tmax, 2), numero(r.tmin, 2), numero(r.tmedia, 2),
                numero(gdd, 2), numero(acum, 2), numero(r.dli, 2), hms(ini), hms(fil), hms(foto),
                numero(typeof foto === "number" ? foto / 3600 : null, 3), numero(cambio, 1),
                typeof foto === "number" ? (conPar ? "PAR" : "lux") : "", numero(r.horas_datos, 1)];
    });
} else {
    columnas = ["fecha_hora", "lote", "ubicacion"].concat(msg.campos);
    datos = filas.map(r => {
        const t = local(r._time);
        const c = cicloDe(t.slice(0, 10));
        return [excel ? t.replace("T", " ") : t + "-05:00", texto(c.lote), texto(c.ubicacion)]
            .concat(msg.campos.map(f => numero(r[f], 3)));
    });
}

if (msg.vista) {
    msg.headers = {"Content-Type": "application/json; charset=utf-8"};
    msg.payload = {ok: true, columnas: columnas, filas: datos.slice(0, 20), mostradas: Math.min(datos.length, 20)};
    return msg;
}

const nombre = "estacion_trigal_" + msg.tipo + "_" + msg.rango.desde + "_" + msg.rango.hasta + (excel ? "_excel" : "") + ".csv";
const lineas = [columnas.join(sep)].concat(datos.map(f => f.join(sep)));
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": 'attachment; filename="' + nombre + '"'
};
msg.payload = (excel ? "﻿" : "") + lineas.join("\r\n") + "\r\n";
return msg;

msg.statusCode = 500;
msg.headers = {"Content-Type": "application/json; charset=utf-8"};
msg.payload = {ok: false, error: "Error al consultar InfluxDB: " + (msg.error ? msg.error.message : "")};
return msg;
